{
  "summary": "The incident was caused by slow latency in the redis-features datastore, which made the in‑process feature cache in fraud‑scorer grow, triggering FRD‑W118 and consequently PAYAPI‑W0310 alerts.",
  "likely_cause": "redis-features latency spikes causing fraud‑scorer cache growth",
  "confidence": "high",
  "claims": [
    {
      "text": "The in‑process feature cache grows without bound when redis‑features is slow, producing FRD‑W118 in fraud‑scorer logs and PAYAPI‑W0310 on payments.",
      "evidence_ids": ["RB-006#0", "RB-006-addendum#0"],
      "quote": "the in‑process feature cache grows without bound when redis‑features is slow, with FRD‑W118 in fraud‑scorer logs and PAYAPI‑W0310 on payments"
    },
    {
      "text": "During the incident redis‑features latency spikes were observed, and memory usage of fraud‑scorer rose until a restart was performed.",
      "evidence_ids": ["INC-0080#1"],
      "quote": "redis‑cli --latency on redis‑features‑01: spikes, but irregular... Memory panel: fraud‑scorer‑02 rising steadily since about 03:40"
    },
    {
      "text": "Restarting fraud‑scorer cleared the FRD‑W118 and PAYAPI‑W0310 only after redis‑features latency returned to normal.",
      "evidence_ids": ["INC-0080#1", "INC-0080#2"],
      "quote": "second rollout restart, this time with the store answering normally... PAYAPI‑W0310 gone"
    }
  ],
  "next_checks": [
    "Monitor redis‑features latency continuously and alert on spikes.",
    "Track fraud‑scorer RSS growth per pod to detect cache creep early.",
    "Verify that redis‑features BGSAVE or heavy key scans are not causing latency."
  ]
}
